<?php use App\Core\Authorization; $teacherView=$teacherView??Authorization::isTeacherOnly(); ?>
<div class="page-heading"><div><p class="eyebrow">People</p><h1><?=Authorization::isTeacherOnly()?'My assigned students':'Students'?></h1><p><?=Authorization::isStudentAdministrator()?'Search and monitor student profiles and current enrollment.':'Students currently enrolled in sections you advise or teach.'?></p></div><?php if(Authorization::isStudentAdministrator()&&(Authorization::allows('students.import')||Authorization::allows('students.create'))):?><div class="list-heading-actions"><?php if(Authorization::allows('students.import')):?><a class="button" href="<?=e(url('/students/import'))?>">Import CSV</a><?php endif;?><?php if(Authorization::allows('students.create')):?><a class="button primary" href="<?=e(url('/students/create'))?>">Add student</a><?php endif;?></div><?php endif;?></div>
<form class="filter-bar" method="get" aria-label="Filter students"><label class="filter-field">Search<input name="q" value="<?=e($q)?>" placeholder="Student number or name"></label><label class="filter-field">Status<select name="status"><option value="">All statuses</option><?php foreach(['active','inactive','graduated','transferred','withdrawn'] as $s):?><option <?=$status===$s?'selected':''?> value="<?=$s?>"><?=e(ucfirst($s))?></option><?php endforeach;?></select></label><button class="button">Search students</button></form>
<section class="card table-card"><table><thead><tr><th scope="col">Student</th><th scope="col">Student no.</th><th scope="col">Current class</th><?php if($teacherView):?><th scope="col">My subjects</th><?php endif;?><th scope="col">Status</th><th scope="col" class="action-column">Actions</th></tr></thead><tbody>
<?php foreach($students as $s):?><tr><td><strong><?=e($s['last_name'].', '.$s['first_name'])?></strong><br><small><?=e($s['email'])?></small></td><td><?=e($s['student_no'])?></td><td><?=e(trim(($s['grade_level']??'').' '.($s['section_name']??'')))?><br><small><?=e($s['school_year']??'Not enrolled')?></small></td><?php if($teacherView):?><td><?php $subjects=array_filter(explode('||',(string)($s['assigned_subjects']??'')));?><?php foreach($subjects as $subject):?><span class="badge"><?=e($subject)?></span> <?php endforeach;?><?php if(!$subjects&&(int)($s['is_section_adviser']??0)===1):?><span class="badge">Class adviser</span><?php endif;?></td><?php endif;?><td><span class="badge"><?=e($s['student_status'])?></span></td><td><a class="button small" href="<?=e(url('/students/'.$s['id']))?>">View</a></td></tr><?php endforeach;?>
<?php if(!$students):?><tr><td colspan="<?=$teacherView?6:5?>" class="empty"><?=Authorization::isTeacherOnly()?'No assigned students were found. Ask an administrator to assign you as a section adviser or subject teacher in Academics.':'No students found.'?></td></tr><?php endif;?>
</tbody></table></section>
